<template>
  <div class="car-content">
    <div class="car-content__header car-content-header">
        <v-pagination
            v-if="TOTALS > 20"
            v-model="pageNum"
            :records="TOTALS"
            :per-page="10"
            @paginate="setPageByTotal"
            :options="paginationOptions"
            class="car-list-header__pagination"
        ></v-pagination>
      <CarListTotals
          class="car-list-header__totals"
      />
    </div>
    <div class="car-content__list car-list">
      <CarListItemHead
          class="car-list__head"
      />
      <CarListItem
          class="car-list__wrapper car-list-wrapper"
          v-for="(carItem, i) in CARS"
          :key="i"
          :number="i"
          :store="carItem"
      />
    </div>
  </div>
</template>

<script>
import CarListItem from '/src/components/CarListItem.vue'
import CarListItemHead from "/src/components/CarListItemHead.vue";
import CarListTotals from "/src/components/CarListTotals.vue";
import {mapActions, mapGetters} from "vuex";

export default {
  name: "CarContent",

  mounted() {
    this.GET_CARS_FROM_API(this.pageNum);
    this.GET_CARS_TOTALS_FROM_API();
  },

  computed: {
    ...mapGetters([
        'CARS',
        'TOTALS'
    ])
  },

  methods: {
    setPageByTotal: function(page) {
      this.pageNum = page;
      this.GET_CARS_FROM_API(page);
    },

    ...mapActions([
      'GET_CARS_FROM_API',
      'GET_CARS_TOTALS_FROM_API'
    ]),
  },

  components: {
    CarListTotals,
    CarListItemHead,
    CarListItem,
  },

  data() {
    return {
      pageNum: 1,

        paginationOptions: {
            chunk: 5,
            texts: {
                count: 'Отображается с {from} по {to} (всего {count} шт.)|{count}',
            }
        },
    };
  }
}
</script>

<style scoped lang="scss">
@import "src/components/style/car-list.scss";
</style>