import CarDismantling from '../components/CarDismantling.vue';
import CarIndex from './../components/CarIndex.vue';
import NotFound from './../components/NotFound.vue';
import VueRouter from "vue-router";

const routes = [
    {
        path: '/',
        name: 'carList',
        component: CarDismantling
    },
    {
        path: '/car/:id',
        name: 'carDetail',
        component: CarIndex
    },
    {
        path: '/create',
        name: 'carCreate',
        component: CarIndex
    },
    {
        path: '*',
        name: 'notFound',
        component: NotFound
    },
];

export default new VueRouter({
    mode:'history',
    base: process.env.BASE_URL,
    routes
});